//! Every operation of the [`polarion`] library as a typed command: a DTO with real types for
//! its arguments and its result. JSON (or any other serde format) only appears at the
//! boundaries, generated by `polarion-commands-derive`: the JSON Schema of the arguments for MCP,
//! the clap command line (feature `cli`), and the serialized result.
//!
//! ```no_run
//! use polarion_commands::{Config, Context, ItemArg, Run, items};
//!
//! # async fn run() -> Result<(), Box<dyn std::error::Error>> {
//! let config = Config::from_env();
//! let polarion = config.connect()?;
//! let cx = Context::new(&polarion, config.project.as_deref());
//!
//! // Typed: the command and its result are Rust types.
//! let get = items::Get { item: "MP-42".parse::<ItemArg>()?, fields: None, custom: Vec::new() };
//! let item: polarion::WorkItem = get.run(&cx).await?;
//! println!("{}", item.title.unwrap_or_default());
//!
//! // By name with JSON arguments, as the front ends do; serialized only at the end.
//! let output = polarion_commands::call(&cx, "items.count", serde_json::json!({"query": "type:task"})).await?;
//! println!("{}", serde_json::to_string(&output)?);
//! # Ok(()) }
//! ```

