/// Every command, grouped by area.
pub fn catalog() -> &'static [Entry] {
    &CATALOG
}

/// A command's catalog entry by full name (`area.name`).
pub fn find(full_name: &str) -> Option<&'static Entry> {
    let (area, name) = full_name.split_once('.')?;
    CATALOG.iter().find(|e| e.area == area && e.name == name)
}

/// The typed command from its name and JSON arguments.
pub fn parse(full_name: &str, arguments: Value) -> Result<AnyCommand> {
    find(full_name)
        .ok_or_else(|| CommandError::invalid(format!("unknown command `{full_name}`")))?
        .parse(arguments)
}

/// Run a command by name with JSON arguments.
pub async fn call(cx: &Context<'_>, full_name: &str, arguments: Value) -> Result<AnyOutput> {
    parse(full_name, arguments)?.run(cx).await
}
